source_format:
{
  "templateId": "accommodation-deposit",
  "templateVersion": 5,
  "title": "Accommodation Deposit",
  "description_template": "{deposit_for} deposit.",
  "sections": [
    {
      "id": "detail",
      "type": "fields",
      "title": "Deposit",
      "layout": "grid",
      "columns": 2,
      "fields": [
        {
          "key": "deposit_for",
          "label": "Deposit For",
          "type": "select",
          "options": [
            "Labour Accommodation",
            "Staff Accommodation",
            "Site Office",
            "Other"
          ],
          "required": true
        }
      ]
    }
  ]
}

{
  "templateId": "statutory-professional",
  "templateVersion": 2,
  "title": "Professional / Statutory Fee",
  "description_template": "Audit fee for {period_or_fy}.",
  "sections": [
    {
      "id": "detail",
      "type": "fields",
      "title": "Engagement",
      "layout": "grid",
      "columns": 2,
      "fields": [
        {
          "key": "period_or_fy",
          "label": "Period / FY",
          "type": "text",
          "required": true
        }
      ]
    }
  ]
}

{
  "templateId": "bank-charge",
  "templateVersion": 2,
  "title": "Bank Charge",
  "description_template": "Bank charges – {bank_name}[[ for {period_month}]].",
  "sections": [
    {
      "id": "detail",
      "type": "fields",
      "title": "Charge",
      "layout": "grid",
      "columns": 2,
      "fields": [
        {
          "key": "bank_name",
          "label": "Bank Name",
          "type": "text",
          "required": true
        },
        {
          "key": "period_month",
          "label": "For the Month",
          "type": "date"
        }
      ]
    }
  ]
}

{
  "templateId": "electricity-bill",
  "templateVersion": 2,
  "title": "Electricity Bill",
  "description_template": "Electricity – {premises}, bill dated {billing_month}.",
  "sections": [
    {
      "id": "detail",
      "type": "fields",
      "title": "Bill",
      "layout": "grid",
      "columns": 2,
      "fields": [
        {
          "key": "premises",
          "label": "Location",
          "type": "select",
          "options": [
            "Office",
            "Store Room",
            "Godown",
            "Other"
          ],
          "required": true
        },
        {
          "key": "billing_month",
          "label": "Bill Date",
          "type": "date",
          "required": true
        }
      ]
    }
  ]
}

{
  "templateId": "hotel-stay",
  "templateVersion": 5,
  "title": "Hotel Stay",
  "description_template": "{guest_name} – hotel stay[[ in {location}]], {check_in} to {check_out}.",
  "sections": [
    {
      "id": "detail",
      "type": "fields",
      "title": "Stay",
      "layout": "grid",
      "columns": 2,
      "fields": [
        {
          "key": "guest_name",
          "label": "Guest Name",
          "type": "text",
          "required": true,
          "bind": "user.full_name"
        },
        {
          "key": "location",
          "label": "City",
          "type": "text"
        },
        {
          "key": "check_in",
          "label": "Check-in",
          "type": "date",
          "required": true
        },
        {
          "key": "check_out",
          "label": "Check-out",
          "type": "date",
          "required": true
        }
      ]
    }
  ]
}

{
  "templateId": "office-rent",
  "templateVersion": 2,
  "title": "Office Rent",
  "description_template": "Office rent for {rent_month} – {office_location}. Landlord: {landlord_name} (PAN {landlord_pan}). (10% TDS will be deducted)",
  "sections": [
    {
      "id": "detail",
      "type": "fields",
      "title": "Rent",
      "layout": "grid",
      "columns": 2,
      "fields": [
        {
          "key": "rent_month",
          "label": "Rent Month",
          "type": "month",
          "required": true
        },
        {
          "key": "office_location",
          "label": "Office Location",
          "type": "text",
          "required": true
        },
        {
          "key": "landlord_name",
          "label": "Landlord Name",
          "type": "text",
          "required": true
        },
        {
          "key": "landlord_pan",
          "label": "Landlord PAN",
          "type": "pan",
          "required": true
        }
      ]
    }
  ]
}

{
  "templateId": "labour-accommodation",
  "templateVersion": 5,
  "title": "Labour Accommodation",
  "description_template": "{accommodation_type}[[ in {city}]], {rent_period_from} to {rent_period_to}, {no_of_occupants} occupant(s).",
  "sections": [
    {
      "id": "detail",
      "type": "fields",
      "title": "Labour Accommodation",
      "layout": "grid",
      "columns": 2,
      "fields": [
        {
          "key": "accommodation_type",
          "label": "Accommodation Type",
          "type": "select",
          "options": [
            "PG",
            "Hotel",
            "Flat / House",
            "Guest House",
            "Other"
          ],
          "required": true
        },
        {
          "key": "city",
          "label": "City",
          "type": "text"
        },
        {
          "key": "rent_period_from",
          "label": "Rent Period From",
          "type": "date",
          "required": true
        },
        {
          "key": "rent_period_to",
          "label": "Rent Period To",
          "type": "date",
          "required": true
        },
        {
          "key": "no_of_occupants",
          "label": "No. of Occupants",
          "type": "number",
          "min": 1,
          "required": true
        }
      ]
    }
  ]
}

{
  "templateId": "staff-accommodation",
  "templateVersion": 9,
  "title": "Staff Accommodation",
  "description_template": "{person_name} – {accommodation_type} accommodation[[ in {city}]][[, from {rent_period_from} to {rent_period_to}]].",
  "sections": [
    {
      "id": "detail",
      "type": "fields",
      "title": "Staff Accommodation",
      "layout": "grid",
      "columns": 2,
      "fields": [
        {
          "key": "person_name",
          "label": "Person Name",
          "type": "text",
          "required": true,
          "bind": "user.full_name"
        },
        {
          "key": "accommodation_type",
          "label": "Accommodation Type",
          "type": "select",
          "options": [
            "PG",
            "Hotel",
            "Flat / House",
            "Guest House",
            "Other"
          ],
          "required": true
        },
        {
          "key": "city",
          "label": "City",
          "type": "text"
        },
        {
          "key": "rent_period_from",
          "label": "Rent Period From",
          "type": "date",
          "required": true
        },
        {
          "key": "rent_period_to",
          "label": "Rent Period To",
          "type": "date",
          "required": true
        }
      ]
    }
  ]
}

{
  "templateId": "repair-service",
  "templateVersion": 2,
  "title": "Repair & Maintenance",
  "description_template": "{service_type} – {work_done} on {service_date}.",
  "sections": [
    {
      "id": "detail",
      "type": "fields",
      "title": "Service",
      "layout": "grid",
      "columns": 2,
      "fields": [
        {
          "key": "service_type",
          "label": "Type",
          "type": "select",
          "options": [
            "Repair",
            "Service / AMC",
            "Spare Part Purchase",
            "Replacement"
          ],
          "required": true
        },
        {
          "key": "work_done",
          "label": "Work Done / Part",
          "type": "textarea",
          "required": true
        },
        {
          "key": "service_date",
          "label": "Date",
          "type": "date",
          "required": true
        }
      ]
    }
  ]
}
